package mysql
import("fmt";"net/url";"strings";"time")
type Config struct{DBName string;Params map[string]string;ParseTime bool;Loc *time.Location;Timeout,ReadTimeout,WriteTimeout time.Duration}
func ParseDSN(dsn string)(*Config,error){c:=&Config{Params:map[string]string{},Loc:time.Local}; slash:=strings.LastIndex(dsn,"/"); if slash>=0{rest:=dsn[slash+1:]; if q:=strings.IndexByte(rest,'?');q>=0{c.DBName=rest[:q]; vals,_:=url.ParseQuery(rest[q+1:]);for k,v:=range vals{if len(v)>0{c.Params[k]=v[0]}};c.ParseTime=c.Params["parseTime"]=="true";if loc:=c.Params["loc"];loc!=""{if z,e:=time.LoadLocation(loc);e==nil{c.Loc=z}};c.Timeout,_=time.ParseDuration(c.Params["timeout"]);c.ReadTimeout,_=time.ParseDuration(c.Params["readTimeout"]);c.WriteTimeout,_=time.ParseDuration(c.Params["writeTimeout"])}else{c.DBName=rest}};return c,nil}
func(c *Config)FormatDSN()string{q:=url.Values{};for k,v:=range c.Params{q.Set(k,v)};if c.ParseTime{q.Set("parseTime","true")};if c.Loc!=nil{q.Set("loc",c.Loc.String())};if c.Timeout>0{q.Set("timeout",c.Timeout.String())};if c.ReadTimeout>0{q.Set("readTimeout",c.ReadTimeout.String())};if c.WriteTimeout>0{q.Set("writeTimeout",c.WriteTimeout.String())};s:="stub@tcp(localhost:3306)/"+c.DBName;if enc:=q.Encode();enc!=""{s+="?"+enc};return s}
type MySQLError struct{Number uint16;Message string};func(e *MySQLError)Error()string{return fmt.Sprintf("Error %d: %s",e.Number,e.Message)}
